// static
bool StructTraits<::ash::diagnostics::mojom::KeyEvent::DataView, ::ash::diagnostics::mojom::KeyEventPtr>::Read(
    ::ash::diagnostics::mojom::KeyEvent::DataView input,
    ::ash::diagnostics::mojom::KeyEventPtr* output) {
  bool success = true;
  ::ash::diagnostics::mojom::KeyEventPtr result(::ash::diagnostics::mojom::KeyEvent::New());
  
      if (success)
        result->id = input.id();
      if (success && !input.ReadType(&result->type))
        success = false;
      if (success)
        result->key_code = input.key_code();
      if (success)
        result->scan_code = input.scan_code();
      if (success)
        result->top_row_position = input.top_row_position();
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::ash::diagnostics::mojom::TouchDeviceInfo::DataView, ::ash::diagnostics::mojom::TouchDeviceInfoPtr>::Read(
    ::ash::diagnostics::mojom::TouchDeviceInfo::DataView input,
    ::ash::diagnostics::mojom::TouchDeviceInfoPtr* output) {
  bool success = true;
  ::ash::diagnostics::mojom::TouchDeviceInfoPtr result(::ash::diagnostics::mojom::TouchDeviceInfo::New());
  
      if (success)
        result->id = input.id();
      if (success && !input.ReadConnectionType(&result->connection_type))
        success = false;
      if (success && !input.ReadType(&result->type))
        success = false;
      if (success && !input.ReadName(&result->name))
        success = false;
      if (success)
        result->testable = input.testable();
  *output = std::move(result);
  return success;
}

