void InputDataProviderAsyncWaiter::GetConnectedDevices(
    std::vector<::ash::diagnostics::mojom::KeyboardInfoPtr>* out_keyboards, std::vector<TouchDeviceInfoPtr>* out_touch_devices) {
  base::RunLoop loop;
  proxy_->GetConnectedDevices(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<::ash::diagnostics::mojom::KeyboardInfoPtr>* out_keyboards
,
             std::vector<TouchDeviceInfoPtr>* out_touch_devices
,
             std::vector<::ash::diagnostics::mojom::KeyboardInfoPtr> keyboards,
             std::vector<TouchDeviceInfoPtr> touch_devices) {*out_keyboards = std::move(keyboards);*out_touch_devices = std::move(touch_devices);
            loop->Quit();
          },
          &loop,
          out_keyboards,
          out_touch_devices));
  loop.Run();
}



